mapper.select:
SELECT ne.id, ne.title, u.user_name as author, ne.summary, c.name AS category_name, ne.word_count, ne.create_time, -- 子查询：聚合标签 (SELECT GROUP_CONCAT(t.name SEPARATOR ', ') FROM note_tag nt LEFT JOIN tag t ON nt.tag_id = t.id WHERE nt.note_id = ne.id) AS tags FROM note ne LEFT JOIN user u ON ne.user_id = u.id LEFT JOIN category c ON ne.category_id = c.id
ne.is_delete = 0 AND ne.visibility = 1 AND ne.status = 1
AND (
ne.title LIKE CONCAT('%', #{keyword}, '%') OR ne.summary LIKE CONCAT('%', #{keyword}, '%')
)
limit #{limit}
